@import "@fontsource-variable/public-sans";
@import "@fontsource-variable/geist-mono";

/* Light (faithful): white page, #f6f6f6 grey panels and bands, #181b25 ink text, #36373a
   graphite secondary text, #ebebeb hairlines, the #ff6631 orange CTA, the #387bf0 blue
   second accent and #1cba6b green status dots. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.224 0.02 272);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.224 0.02 272);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.224 0.02 272);
  --primary: oklch(0.698 0.198 38);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.973 0 90);
  --secondary-foreground: oklch(0.224 0.02 272);
  --muted: oklch(0.973 0 90);
  --muted-foreground: oklch(0.337 0.005 271);
  --accent: oklch(0.94 0 90);
  --accent-foreground: oklch(0.224 0.02 272);
  --destructive: oklch(0.6 0.23 20);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.94 0 90);
  --input: oklch(0.94 0 90);
  --ring: oklch(0.604 0.189 261);
  --highlight: oklch(0.604 0.189 261);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.6 0.16 258);
  --chart-1: oklch(0.698 0.198 38);
  --chart-2: oklch(0.695 0.168 154);
  --chart-3: oklch(0.604 0.189 261);
  --chart-4: oklch(0.909 0.043 255);
  --chart-5: oklch(0.216 0.02 276);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.224 0.02 272);
  --sidebar-primary: oklch(0.698 0.198 38);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.973 0 90);
  --sidebar-accent-foreground: oklch(0.224 0.02 272);
  --sidebar-border: oklch(0.94 0 90);
  --sidebar-ring: oklch(0.604 0.189 261);

  --typeface-body: "Public Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Public Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.25rem;
  --page-width: 74.5rem;
  --page-gutter: 1.25rem;
  --section-y: 7rem;
}

/* Dark sibling (and the hero, stat card and footer in light mode): the #171923 blue-black
   ink page, #1e2130 raised panels (the original's hover colour), white text, white-80%
   secondary text, translucent white hairlines; the same orange and blue. */
.dark {
  --background: oklch(0.216 0.02 276);
  --foreground: oklch(1 0 0);
  --card: oklch(0.252 0.029 275);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.252 0.029 275);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.698 0.198 38);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.281 0.03 276);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.252 0.029 275);
  --muted-foreground: oklch(0.891 0 90);
  --accent: oklch(0.313 0.033 275);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.66 0.22 20);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 18%);
  --ring: oklch(0.787 0.108 259);
  --highlight: oklch(0.64 0.18 261);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.62 0.16 258);
  --chart-1: oklch(0.698 0.198 38);
  --chart-2: oklch(0.695 0.168 154);
  --chart-3: oklch(0.64 0.18 261);
  --chart-4: oklch(0.787 0.108 259);
  --chart-5: oklch(0.891 0 90);
  --sidebar: oklch(0.216 0.02 276);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.698 0.198 38);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.281 0.03 276);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 12%);
  --sidebar-ring: oklch(0.787 0.108 259);
}
